// Works out who asked (Telegram, WhatsApp or the n8n chat) and prepares the request
// that lets Claude extract destination, start point and day(s) from the free text.
const cfg = $('Configure Outing Radar').first().json;
const req = $input.first().json;

let channel, chatId, text = '', phoneNumberId = '';
if (typeof req.chatInput === 'string') {
  channel = 'chat';
  chatId = String(req.sessionId || '');
  text = req.chatInput;
} else if (req.message && req.message.chat) {
  channel = 'telegram';
  chatId = String(req.message.chat.id);
  text = req.message.text || '';
} else if (Array.isArray(req.messages) && req.messages[0]) {
  const msg = req.messages[0];
  channel = 'whatsapp';
  chatId = String(msg.from);
  text = msg.type === 'text' ? (msg.text && msg.text.body) || '' : '';
  phoneNumberId = (req.metadata && req.metadata.phone_number_id) || '';
} else {
  return []; // e.g. a WhatsApp delivery receipt
}

// Optional allow list for Telegram and WhatsApp, so strangers who find the bot cannot
// run up your API bill. The n8n chat is protected by its own authentication instead.
const allowed = String(cfg.allowedChatIds || '').split(',').map(s => s.trim()).filter(Boolean);
if ((channel === 'telegram' || channel === 'whatsapp') && allowed.length && !allowed.includes(chatId)) return [];
if (!text.trim()) return [];

const tz = cfg.timezone || 'UTC';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date());
const addDays = (d, n) => { const t = new Date(d + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
const weekday = d => new Intl.DateTimeFormat('en-GB', { weekday: 'long', timeZone: 'UTC' }).format(new Date(d + 'T00:00:00Z'));
const calendar = Array.from({ length: 21 }, (_, i) => `${addDays(today, i)} ${weekday(addDays(today, i))}`).join('\n');

const place = '{"name":"place as the person calls it","geocodeName":"nearest village or town, plain name only",' +
  '"countryCode":"ISO 3166-1 alpha-2","transitStop":"nearest public transport stop or station","type":"e.g. family hike, lake, zoo, city"}';

return [{
  json: {
    channel, chatId, phoneNumberId, text, today,
    extractRequest: {
      model: cfg.claudeModel,
      max_tokens: 600,
      messages: [{
        role: 'user',
        content:
          `Today is ${today} (${weekday(today)}), time zone ${tz}. Calendar of the next days:\n${calendar}\n\n` +
          'Read the message below from someone planning a day trip. Extract the destination, the start point ' +
          '(only if the message mentions one) and the day(s) they want to go. If no day is mentioned, use the ' +
          'upcoming Saturday and Sunday (only Sunday if today is Sunday). Use at most 3 dates.\n' +
          `Reply with ONLY a JSON object, no other text: {"destination":${place} or null,"origin":${place} or null,` +
          '"dates":["YYYY-MM-DD"],"language":"ISO 639-1 code of the message"}\n\n' +
          `Message: """${text.slice(0, 500)}"""`,
      }],
    },
  },
}];

// Reads Claude's answer. Without a destination the workflow replies with a short help text,
// otherwise it prepares the request for similar, possibly quieter alternatives.
const cfg = $('Configure Outing Radar').first().json;
const msg = $('Identify Message Source').first().json;
const res = $input.first().json;

let trip = {};
try {
  const txt = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  trip = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
} catch (e) { trip = {}; }

const pref = String(cfg.replyLanguage || 'auto').toLowerCase();
const lang = pref === 'auto' ? (String(trip.language || '').toLowerCase().startsWith('de') ? 'de' : 'en') : (pref.startsWith('de') ? 'de' : 'en');

const addDays = (d, n) => { const t = new Date(d + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
const dow = new Date(msg.today + 'T00:00:00Z').getUTCDay();
const sat = addDays(msg.today, (6 - dow + 7) % 7);
let dates = [...new Set((trip.dates || []).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d) && d >= msg.today))].sort().slice(0, 3);
if (!dates.length) dates = dow === 0 ? [msg.today] : [sat, addDays(sat, 1)];

const valid = p => p && typeof p === 'object' && String(p.name || '').trim() ? p : null;
const destination = valid(trip.destination);
const origin = valid(trip.origin);

if (!destination) {
  const help = res.error
    ? (lang === 'de' ? 'Entschuldigung, ich konnte deine Nachricht gerade nicht auswerten. Versuch es bitte später nochmals.'
                     : 'Sorry, I could not read your message right now. Please try again later.')
    : (lang === 'de' ? 'Wohin soll der Ausflug gehen? Schreib zum Beispiel: «Sonntag Klewenalp ab Basel».'
                     : 'Where would you like to go? Try something like: "Sunday Klewenalp from Basel".');
  const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  return [{ json: { found: false, channel: msg.channel, chatId: msg.chatId, phoneNumberId: msg.phoneNumberId,
    telegramText: esc(help), whatsappText: help, chatText: help } }];
}

const n = Math.max(0, Math.min(3, Number(cfg.alternativesCount) || 0));
const from = origin ? `from ${origin.name}` : `from the area around ${destination.name}`;
return [{
  json: {
    found: true, channel: msg.channel, chatId: msg.chatId, phoneNumberId: msg.phoneNumberId,
    lang, dates, destination, origin,
    altRequest: {
      model: cfg.claudeModel,
      max_tokens: 800,
      messages: [{
        role: 'user',
        content:
          `Someone wants to go to "${destination.name}" (${destination.type || 'day trip'}, ${destination.countryCode || ''}) ` +
          `on ${dates.join(' and ')}, travelling ${from}. Suggest ${n} alternative destinations that offer a similar ` +
          'experience, need a similar travel time and are usually less crowded. Do not suggest the original destination. ' +
          `Reply with ONLY a JSON object, no other text: {"alternatives":[{"name":"","geocodeName":"nearest village or town, plain name only",` +
          `"countryCode":"ISO 3166-1 alpha-2","transitStop":"nearest public transport stop or station","why":"max 8 words in ${lang === 'de' ? 'German' : 'English'}"}]}`,
      }],
    },
  },
}];

// Collects the places to check: the requested destination, Claude's alternatives and the start point.
const cfg = $('Configure Outing Radar').first().json;
const trip = $('Analyze API Response').first().json;
const res = $input.first().json;

let alternatives = [];
try {
  const txt = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  alternatives = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)).alternatives || [];
} catch (e) { alternatives = []; }

const clean = (p, role) => ({
  role,
  name: String(p.name || '').trim(),
  geocodeName: String(p.geocodeName || p.name || '').trim(),
  countryCode: String(p.countryCode || '').toUpperCase().slice(0, 2),
  transitStop: String(p.transitStop || '').trim(),
  why: String(p.why || '').trim(),
});

const out = [clean(trip.destination, 'target')];
const seen = new Set([out[0].name.toLowerCase()]);
for (const a of alternatives.slice(0, Math.min(3, Number(cfg.alternativesCount) || 0))) {
  const p = clean(a || {}, 'alternative');
  if (!p.name || seen.has(p.name.toLowerCase())) continue;
  seen.add(p.name.toLowerCase());
  out.push(p);
}
if (trip.origin) out.push(clean(trip.origin, 'origin'));
return out.map(json => ({ json }));

// One item per country of the places found, so holidays are loaded once per country.
const trip = $('Analyze API Response').first().json;
const places = $('Compile Place List').all().map(i => i.json);
const geo = $('Get Geocodes for Places').all().map(i => i.json);

const addDays = (d, n) => { const t = new Date(d + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
const from = addDays(trip.dates[0], -182);
const to = addDays(trip.dates[trip.dates.length - 1], 182);
const lang = trip.lang.toUpperCase();

const countries = [...new Set(places.map((p, i) => {
  const g = geo[i] && Array.isArray(geo[i].results) && geo[i].results[0];
  return p.role !== 'origin' && g ? g.country_code : null;
}).filter(Boolean))];

const OH = 'https://openholidaysapi.org';
return (countries.length ? countries : ['']).map(c => ({
  json: {
    country: c,
    subdivisionsUrl: c ? `${OH}/Subdivisions?countryIsoCode=${c}&languageIsoCode=EN` : '',
    schoolUrl: c ? `${OH}/SchoolHolidays?countryIsoCode=${c}&languageIsoCode=${lang}&validFrom=${from}&validTo=${to}` : '',
    publicUrl: c ? `${OH}/PublicHolidays?countryIsoCode=${c}&languageIsoCode=${lang}&validFrom=${from}&validTo=${to}` : '',
  },
}));

// One item per place found (without the start point), with everything the next lookups need:
// region for school holidays, weather URL, driving and public transport URLs, event search request.
const cfg = $('Configure Outing Radar').first().json;
const trip = $('Analyze API Response').first().json;
const places = $('Compile Place List').all().map(i => i.json);
const geo = $('Get Geocodes for Places').all().map(i => i.json);
const countries = $('Organize Country Data').all().map(i => i.json);
const subsRes = $('Get Country Subdivisions').all().map(i => i.json);

const subsBy = {};
countries.forEach((c, i) => { const b = subsRes[i] && subsRes[i].body; subsBy[c.country] = Array.isArray(b) ? b : []; });
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const findSubdivision = (cc, admin1) => {
  const a = norm(admin1);
  const list = subsBy[cc] || [];
  if (!a) return '';
  const names = s => [...(s.name || []).map(n => norm(n.text)), norm(s.shortName)];
  const hit = list.find(s => names(s).includes(a)) || list.find(s => names(s).some(t => t.length > 3 && (t.includes(a) || a.includes(t))));
  return hit ? hit.code : '';
};
const top = i => (geo[i] && Array.isArray(geo[i].results) && geo[i].results[0]) || null;

const oi = places.findIndex(p => p.role === 'origin');
const origin = oi >= 0 ? places[oi] : null;
const og = oi >= 0 ? top(oi) : null;
const enc = encodeURIComponent;
const lang = trip.lang === 'de' ? 'German' : 'English';

const out = [];
places.forEach((p, i) => {
  if (p.role === 'origin') return;
  const g = top(i);
  if (!g) return;
  const where = [p.name, g.admin1, g.country].filter(Boolean).join(', ');
  out.push({
    role: p.role, name: p.name, why: p.why,
    lat: g.latitude, lon: g.longitude, countryCode: g.country_code,
    subdivisionCode: findSubdivision(g.country_code, g.admin1),
    weatherUrl: `https://api.open-meteo.com/v1/forecast?latitude=${g.latitude}&longitude=${g.longitude}` +
      '&daily=weather_code,temperature_2m_max,precipitation_sum,precipitation_probability_max&timezone=auto&past_days=7&forecast_days=16',
    carUrl: og ? `https://router.project-osrm.org/route/v1/driving/${og.longitude},${og.latitude};${g.longitude},${g.latitude}?overview=false` : '',
    transitUrl: og && og.country_code === 'CH' && g.country_code === 'CH'
      ? `https://transport.opendata.ch/v1/connections?from=${enc(origin.transitStop || origin.geocodeName)}` +
        `&to=${enc(p.transitStop || p.geocodeName)}&date=${trip.dates[0]}&time=${enc(cfg.departureTime || '08:30')}&limit=4`
      : '',
    eventRequest: {
      model: cfg.claudeModel,
      max_tokens: 1200,
      tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: Number(cfg.maxSearchesPerPlace) || 2 }],
      messages: [{
        role: 'user',
        content:
          `Search the web for events on ${trip.dates.join(', ')} at or near "${where}" that could make it unusually crowded ` +
          'for day trippers: festivals, organised hiking or family days, races, markets, concerts, promotions by cable cars, ' +
          'railways or retailers, or closures. Only count events that clearly take place on one of these dates. ' +
          'Reply with ONLY a JSON object, no other text: {"days":{"YYYY-MM-DD":{"impact":"none|low|medium|high",' +
          `"events":[{"title":"short title","note":"max 12 words"}]}}}. Write title and note in ${lang}. ` +
          'Use impact "none" and an empty list for dates without specific events.',
      }],
    },
  });
});

if (!out.length) return [{ json: { notFound: true, weatherUrl: '', carUrl: '', transitUrl: '', eventRequest: null } }];
return out.map(json => ({ json }));

// Combines holidays, weather, travel time and event hints into a crowd score per place and day
// and writes the reply for Telegram, WhatsApp, the n8n chat and the optional email copy.
const cfg = $('Configure Outing Radar').first().json;
const trip = $('Analyze API Response').first().json;
const places = $('Compile Place List').all().map(i => i.json);
const geo = $('Get Geocodes for Places').all().map(i => i.json);
const checks = $('Set Up Place Verification').all().map(i => i.json);
const get = n => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
const weather = get('Fetch Weather Forecast');
const car = get('Fetch Driving Time');
const transit = get('Fetch Transit Time');
const events = get('Search Local Events');
const countries = get('Prepare Countries');
const bodyOf = n => { const r = get(n); const m = {}; countries.forEach((c, i) => { m[c.country] = Array.isArray(r[i] && r[i].body) ? r[i].body : []; }); return m; };
const schoolBy = bodyOf('Fetch School Holidays');
const publicBy = bodyOf('Fetch Public Holidays');
const subsBy = bodyOf('Fetch Subdivisions');

const de = trip.lang === 'de';
const T = de ? {
  title: 'Ausflugs-Radar', quiet: 'ruhig', moderate: 'mittel', busy: 'viel los',
  better: 'Ruhigere Alternative:', betterWeather: 'Besseres Wetter:', good: 'Gute Wahl, ruhiger wird es in der Nähe kaum.', others: 'Weitere Optionen',
  allBad: 'Das Wetter sieht überall durchzogen aus.', pubHoliday: n => `Feiertag: ${n}`,
  school: (a, b) => `Schulferien in ${a} von ${b} Regionen`, schoolHere: 'Schulferien in der Region',
  weekend: d => (d === 0 ? 'Sonntag' : 'Samstag'), catchUp: 'erster schöner Tag nach Regen', badWeather: 'schlechtes Wetter',
  noForecast: 'noch keine Prognose', noEvents: 'Event-Suche nicht verfügbar',
  noOrigin: 'Tipp: Schreib deinen Startort dazu (z. B. «ab Basel»), dann rechne ich auch die Anfahrt.',
  notFound: n => `Nicht gefunden: ${n}. Versuch es mit dem nächsten Dorf oder Ort.`,
  nothing: n => `Ich konnte «${n}» leider nicht finden. Versuch es mit dem nächsten Dorf oder Ort.`,
  subject: (n, d, l) => `Ausflugs-Radar: ${n} am ${d} – ${l}`, locale: 'de-CH',
} : {
  title: 'Outing radar', quiet: 'quiet', moderate: 'moderate', busy: 'busy',
  better: 'Quieter alternative:', betterWeather: 'Better weather:', good: 'Good choice, it hardly gets quieter nearby.', others: 'Other options',
  allBad: 'The weather looks mixed everywhere.', pubHoliday: n => `Public holiday: ${n}`,
  school: (a, b) => `School holidays in ${a} of ${b} regions`, schoolHere: 'school holidays in the region',
  weekend: d => (d === 0 ? 'Sunday' : 'Saturday'), catchUp: 'first nice day after rain', badWeather: 'poor weather',
  noForecast: 'no forecast yet', noEvents: 'event search unavailable',
  noOrigin: 'Tip: add your start point (e.g. "from Basel") and I will add travel times.',
  notFound: n => `Not found: ${n}. Try the nearest village or town.`,
  nothing: n => `Sorry, I could not find "${n}". Try the nearest village or town.`,
  subject: (n, d, l) => `Outing radar: ${n} on ${d} – ${l}`, locale: 'en-GB',
};

const inRange = (h, d) => h.startDate <= d && d <= (h.endDate || h.startDate);
const inRegion = (h, code) => h.nationwide || !code ||
  (h.subdivisions || []).some(s => s.code === code || s.code.startsWith(code + '-') || code.startsWith(s.code + '-'));
const nameOf = h => { const n = h.name || []; return (n.find(x => x.language === trip.lang.toUpperCase()) || n[0] || {}).text || ''; };
const wxIcon = c => (c == null ? '❔' : c <= 1 ? '☀️' : c === 2 ? '🌤️' : c === 3 ? '☁️' : c <= 48 ? '🌫️'
  : (c >= 71 && c <= 77) || c === 85 || c === 86 ? '🌨️' : c >= 95 ? '⛈️' : '🌧️');
const minutesOf = s => { const m = String(s || '').match(/(\d+)d(\d+):(\d+):(\d+)/); return m ? (+m[1]) * 1440 + (+m[2]) * 60 + (+m[3]) : null; };

const scored = [];
if (!checks[0] || !checks[0].notFound) {
  checks.forEach((pl, idx) => {
    const school = schoolBy[pl.countryCode] || [];
    const pub = publicBy[pl.countryCode] || [];
    const regions = (subsBy[pl.countryCode] || []).map(s => s.code);
    const allRegions = regions.length ? regions : [...new Set(school.flatMap(h => (h.subdivisions || []).map(s => s.code)))];

    // Travel time (same for all days)
    const route = car[idx] && Array.isArray(car[idx].routes) && car[idx].routes[0];
    const carMin = route ? Math.round(route.duration / 60) : null;
    const conns = (transit[idx] && Array.isArray(transit[idx].connections) ? transit[idx].connections : [])
      .map(c => minutesOf(c.duration)).filter(m => m != null);
    const transitMin = conns.length ? Math.min(...conns) : null;

    let ev = null;
    const e = events[idx];
    if (e && !e.error && Array.isArray(e.content)) {
      try {
        const txt = e.content.filter(b => b.type === 'text').map(b => b.text).join('');
        ev = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)).days || {};
      } catch (err) { ev = null; }
    }

    for (const date of trip.dates) {
      const reasons = [];
      let score = 0;
      const day = new Date(date + 'T00:00:00Z').getUTCDay();
      if (day === 0) score += 2; else if (day === 6) score += 1.5;
      if (day === 0 || day === 6) reasons.push(T.weekend(day));

      const hol = pub.filter(h => inRange(h, date));
      const local = hol.find(h => inRegion(h, pl.subdivisionCode));
      if (local) { score += 2.5; reasons.push(T.pubHoliday(nameOf(local))); } else if (hol.length) score += 0.5;

      const onHoliday = allRegions.filter(code => school.some(h => inRange(h, date) && inRegion(h, code)));
      const share = allRegions.length ? onHoliday.length / allRegions.length : 0;
      score += 2.5 * share;
      if (share >= 0.15) reasons.push(T.school(onHoliday.length, allRegions.length));
      if (pl.subdivisionCode && onHoliday.includes(pl.subdivisionCode)) { score += 0.5; if (share < 0.15) reasons.push(T.schoolHere); }

      const daily = (weather[idx] && weather[idx].daily) || {};
      const di = (daily.time || []).indexOf(date);
      let wx = { known: false, ok: true, icon: '❔', temp: null };
      if (di >= 0) {
        const code = daily.weather_code[di];
        const prob = (daily.precipitation_probability_max || [])[di];
        const nice = code <= 3 && (prob == null || prob <= 30);
        const bad = code >= 61 || (prob != null && prob >= 60);
        const rainyBefore = [1, 2, 3].filter(k => di - k >= 0 && (daily.precipitation_sum[di - k] || 0) >= 2).length;
        wx = { known: true, ok: !bad, icon: wxIcon(code), temp: Math.round(daily.temperature_2m_max[di]) };
        if (nice) score += 1;
        if (bad) { score -= 2; reasons.push(T.badWeather); }
        if (nice && rainyBefore >= 2) { score += 1; reasons.push(T.catchUp); }
      }

      let found = [];
      const d = ev && ev[date];
      if (d) {
        const impact = ['none', 'low', 'medium', 'high'].includes(d.impact) ? d.impact : 'none';
        score += { none: 0, low: 1, medium: 2.5, high: 4 }[impact];
        if (impact !== 'none') found = (d.events || []).filter(x => x && x.title).slice(0, 2);
      }

      score = Math.round(Math.min(10, Math.max(0, score)) * 2) / 2;
      scored.push({ ...pl, idx, date, score, level: score < 4 ? 'quiet' : score < 7 ? 'moderate' : 'busy',
        wx, found, reasons, carMin, transitMin, eventsOk: !cfg.useEventSearch || ev !== null });
    }
  });
}

// --- Reply ---
const dot = { quiet: '🟢', moderate: '🟡', busy: '🔴' };
const fmtDate = d => new Intl.DateTimeFormat(T.locale, { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' })
  .format(new Date(d + 'T00:00:00Z'));
const dur = m => (m == null ? null : m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')}`);
const travel = r => [r.carMin != null ? `🚗 ${dur(r.carMin)}` : '', r.transitMin != null ? `🚆 ${dur(r.transitMin)}` : ''].filter(Boolean).join(' ');
const fastest = r => Math.min(r.carMin ?? Infinity, r.transitMin ?? Infinity);
const missing = places.filter((p, i) => p.role === 'target' && !(geo[i] && Array.isArray(geo[i].results) && geo[i].results[0])).map(p => p.name);

const render = ({ bold, esc, nl, credit }) => {
  const lines = [];
  if (!scored.length) {
    lines.push(esc(T.nothing(trip.destination.name)));
  } else {
    for (const date of trip.dates) {
      const day = scored.filter(r => r.date === date);
      const target = day.find(r => r.role === 'target');
      const ranked = [...day].sort((a, b) => a.score - b.score || fastest(a) - fastest(b));
      const best = ranked.find(r => r.wx.known && r.wx.ok) || ranked.find(r => r.wx.ok) || ranked[0];
      const wxText = r => (r.wx.known ? `${r.wx.icon} ${r.wx.temp}°` : T.noForecast);
      const line = r => [`${dot[r.level]} ${bold(esc(r.name))} – ${T[r.level]} (${r.score}/10)`, wxText(r), travel(r)].filter(Boolean).join(' · ');

      lines.push(`🧭 ${bold(esc(`${T.title} · ${fmtDate(date)}`))}`);
      const main = target || best;
      lines.push(line(main));
      [...main.found.map(e => `${e.title}${e.note ? ': ' + e.note : ''}`), ...main.reasons].slice(0, 4).forEach(x => lines.push(`  • ${esc(x)}`));
      // Suggest the alternative if it is clearly quieter, or if it has good weather while the target has not
      const quieter = target && best !== target && best.score <= target.score - 1.5;
      const drier = target && best !== target && !target.wx.ok && best.wx.known && best.wx.ok;
      const shown = quieter || drier ? best : null;
      if (shown) {
        lines.push('', `${esc(quieter ? T.better : T.betterWeather)} ${line(best)}`);
        if (best.why) lines.push(`  • ${esc(best.why)}`);
      } else if (target) lines.push(esc(T.good));
      if (!day.some(r => r.wx.ok)) lines.push(esc(T.allBad));
      const rest = ranked.filter(r => r !== main && r !== shown);
      if (rest.length) {
        lines.push('', bold(esc(T.others)));
        rest.forEach(r => lines.push(`${line(r)}${r.why ? ' – ' + esc(r.why) : ''}`));
      }
      if (day.some(r => !r.eventsOk)) lines.push(`(${esc(T.noEvents)})`);
      lines.push('');
    }
    if (missing.length) lines.push(esc(T.notFound(missing.join(', '))));
    if (!trip.origin) lines.push(esc(T.noOrigin));
  }
  if (cfg.showAttribution) lines.push(credit);
  while (lines.length && lines[lines.length - 1] === '') lines.pop();
  return lines.join(nl);
};

const escHtml = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const credit = 'Template by Dominik Vogt – linkedin.com/in/dominik-vogt-2b070364';
const firstTarget = scored.find(r => r.role === 'target') || scored[0];
const reply = {
  telegramText: render({ bold: s => `<b>${s}</b>`, esc: escHtml, nl: '\n', credit }),
  whatsappText: render({ bold: s => `*${s}*`, esc: s => String(s ?? ''), nl: '\n', credit }),
  chatText: render({ bold: s => `**${s}**`, esc: s => String(s ?? '').replace(/([*_`\\])/g, '\\$1'), nl: '  \n', credit }),
  emailSubject: firstTarget ? T.subject(firstTarget.name, fmtDate(firstTarget.date), T[firstTarget.level]) : T.title,
  emailHtml: `<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;line-height:1.5;color:#111827">${render({
    bold: s => `<b>${s}</b>`, esc: escHtml, nl: '<br>',
    credit: '<span style="color:#6b7280;font-size:12px">Template by <a href="https://www.linkedin.com/in/dominik-vogt-2b070364/" style="color:#6b7280">Dominik Vogt</a></span>',
  })}</div>`,
  ranking: scored.map(r => ({ date: r.date, name: r.name, role: r.role, score: r.score, level: r.level, carMin: r.carMin, transitMin: r.transitMin, reasons: r.reasons, events: r.found })),
};

// Answer where the question was asked, plus an optional email copy
const out = [{ json: { ...reply, channel: trip.channel, chatId: trip.chatId, phoneNumberId: trip.phoneNumberId } }];
const copy = String(cfg.emailCopyTo || '').trim();
if (copy && !copy.endsWith('@example.com') && trip.channel !== 'email') out.push({ json: { ...reply, channel: 'email', chatId: copy } });
return out;
